const expected={
  'gate5-positive':'FOUND',
  'gate5-wrong-vendor':'NOT_FOUND_OR_NOT_AUTHORIZED',
  'gate5-no-permission':'NOT_FOUND_OR_NOT_AUTHORIZED',
  'gate5-unknown':'AUTH_REQUIRED',
};
const required=new Set(Object.keys(expected));
for (const item of items) {
  const j=item.json;
  if (!j || !required.has(j.trace_id)) throw new Error('Unexpected Gate-5 trace_id');
  if (j.decision!==expected[j.trace_id]) throw new Error('Gate-5 decision mismatch for '+j.trace_id+': '+j.decision);
  if (j.trace_id==='gate5-positive') {
    if (j.invoice_reference!=='__CASE003_GATE5_INVOICE_REFERENCE__') throw new Error('Positive invoice mismatch');
    if (j.company_code!=='__CASE003_GATE5_COMPANY_CODE__') throw new Error('Positive company scope mismatch');
    if (j.fi_document_number!=='__CASE003_GATE5_FI_DOCUMENT__') throw new Error('Positive FI document mismatch');
    if (j.snapshot_id!=='__CASE003_GATE5_SNAPSHOT_ID__') throw new Error('Positive snapshot mismatch');
  } else {
    for (const k of ['invoice_reference','company_code','fi_document_number','snapshot_id']) {
      if (j[k]!==null && j[k]!==undefined) throw new Error('Denied/auth-required case leaked '+k+' for '+j.trace_id);
    }
  }
  required.delete(j.trace_id);
}
if (required.size) throw new Error('Missing Gate-5 decisions: '+[...required].join(','));
return items.map(item=>({json:{...item.json,gate5Assertion:true}}));

return items.map(item=>{
  const j=item.json;
  if (j.decision==='FOUND') {
    return {json:{
      trace_id:j.trace_id,
      decision:j.decision,
      response_type:'invoice_status',
      invoice_reference:j.invoice_reference,
      company_code:j.company_code,
      fi_document_number:j.fi_document_number,
      canonical_due_date:j.canonical_due_date,
      due_date_source:j.due_date_source,
      due_date_conflict:j.due_date_conflict,
      payment_status_evidence:j.payment_status_evidence,
      days_to_due:j.days_to_due,
      overdue_days:j.overdue_days,
      published_at:j.published_at,
      snapshot_id:j.snapshot_id,
      safe_to_respond:true,
      channel_delivery:'disabled'
    }};
  }
  if (j.decision==='AUTH_REQUIRED') {
    return {json:{trace_id:j.trace_id,decision:j.decision,response_type:'verification_required',safe_to_respond:true,channel_delivery:'disabled'}};
  }
  return {json:{trace_id:j.trace_id,decision:j.decision,response_type:'neutral_not_found_or_not_authorized',safe_to_respond:true,channel_delivery:'disabled'}};
});
